import { NextResponse } from 'next/server';
import { sendPaymentSuccessEmail } from '@/utils/email';

export async function POST(request: Request) {
    try {
        const body = await request.json();
        const { email } = body;

        if (!email) {
            return NextResponse.json({ success: false, message: 'Email is required' }, { status: 400 });
        }

        console.log(`Debug: Attempting to send test email to ${email}`);

        await sendPaymentSuccessEmail({
            to: email,
            name: 'Debug User',
            amount: '1.00',
            orderId: 'DEBUG-TEST-ORDER',
            utr: 'DEBUG-UTR-123',
            date: new Date().toLocaleString()
        });

        return NextResponse.json({ success: true, message: 'Email send initiated. Check logs.' });
    } catch (error) {
        console.error('Debug API Error:', error);
        return NextResponse.json({ success: false, message: 'Internal Server Error', error: String(error) }, { status: 500 });
    }
}
